CREATE TABLE orders (
  order_id      NUMBER        PRIMARY KEY,
  customer_name VARCHAR2(50)  NOT NULL,
  amount        NUMBER(10,2)  NOT NULL,
  status        VARCHAR2(20)  NOT NULL,
  order_date    DATE          NOT NULL
);

INSERT INTO orders VALUES (101, 'Asha',  2500, 'SHIPPED',   DATE '2026-10-01');
INSERT INTO orders VALUES (102, 'Ravi',  1200, 'PENDING',   DATE '2026-10-03');
INSERT INTO orders VALUES (103, 'Meera',  800, 'PENDING',   DATE '2026-10-05');
INSERT INTO orders VALUES (104, 'John',  4300, 'CANCELLED', DATE '2026-10-06');
INSERT INTO orders VALUES (105, 'Priya', 1500, 'PENDING',   DATE '2026-10-08');
COMMIT;

DELETE FROM orders WHERE status = 'PENDING';
COMMIT;

SELECT order_id, customer_name, status FROM orders ORDER BY order_id;

SELECT order_id, customer_name, amount, status
  FROM orders AS OF TIMESTAMP (SYSTIMESTAMP - INTERVAL '15' MINUTE)
 ORDER BY order_id;

SELECT *
  FROM orders AS OF TIMESTAMP
       TO_TIMESTAMP('2026-10-31 10:40:00', 'YYYY-MM-DD HH24:MI:SS');

CREATE TABLE orders_recovered AS
  SELECT *
    FROM orders AS OF TIMESTAMP (SYSTIMESTAMP - INTERVAL '15' MINUTE);

SELECT *
  FROM orders AS OF SCN 4518731
 ORDER BY order_id;

SELECT object_name, original_name, droptime
  FROM user_recyclebin
 WHERE original_name = 'ORDERS';

FLASHBACK TABLE orders TO BEFORE DROP;

-- if a new ORDERS table was already created:
FLASHBACK TABLE orders TO BEFORE DROP RENAME TO orders_old;

SELECT value AS undo_retention_seconds
  FROM v$parameter
 WHERE name = 'undo_retention';

SELECT MAX(tuned_undoretention) AS tuned_seconds
  FROM v$undostat;
